parameters.jsCode:
// Builds the alert email. Falls back to a safe reply if the AI step returned nothing.
const d = $('Your business details').item.json;
const first = String(d.Name || '').trim().split(/\s+/)[0] || 'there';
let reply = String($json.choices?.[0]?.message?.content || '').trim()
  .replace(/\*\*(.+?)\*\*/g, '$1').replace(/^#+\s*/gm, '');
const aiOk = reply.length > 20;
if (!aiOk) reply = `Hi ${first},\n\nThanks for getting in touch with ${d.businessName}. We've received your message and will get back to you shortly.\n\n${d.signOffName}\n${d.businessName}`;
const esc = v => String(v || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const subject = `Re: your enquiry to ${d.businessName}`;
const mailto = `mailto:${encodeURIComponent(d.Email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(reply)}`;
const need = d['What do you need help with?'];
const html = `<div style="font-family:Arial,sans-serif;max-width:640px">
<h2 style="margin:0 0 8px">New lead: ${esc(d.Name)}</h2>
<p style="margin:0 0 4px">${esc(d.Email)}${d.Phone ? ' &middot; ' + esc(d.Phone) : ''}</p>
<p style="background:#f6f6f6;border-left:3px solid #999;padding:8px 12px;white-space:pre-wrap">${esc(need)}</p>
<h3 style="margin:18px 0 6px">Suggested reply</h3>
<pre style="white-space:pre-wrap;font-family:Arial,sans-serif;background:#f6f6f6;padding:12px;border-radius:6px">${esc(reply)}</pre>
<p><a href="${mailto}" style="background:#ff6d5a;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none">Reply now</a></p>
${aiOk ? '' : '<p style="color:#b00">The AI step returned no text, so a fallback reply is shown. Check your OpenAI credential.</p>'}
</div>`;
return { json: { to: d.alertEmail, subject: `New lead: ${d.Name} - ${String(need).slice(0, 50)}`, html, reply, aiOk } };
